/* ── 캐러셀 갤러리 ──────────────────────────────────────── */
export function ComponentGallery() {
  const [cur, setCur] = useState(0)
  const [slideW, setSlideW] = useState(0)
  const navRef  = useRef(null)
  const wrapRef = useRef(null)
  const total = COMPONENTS.length

  // wrapper 실제 픽셀 너비 측정 (resize 대응)
  useEffect(() => {
    if (!wrapRef.current) return
    const ro = new ResizeObserver(([entry]) => {
      setSlideW(entry.contentRect.width)
    })
    ro.observe(wrapRef.current)
    return () => ro.disconnect()
  }, [])

  // 네비 토글 클릭 시 해당 버튼 스크롤
  useEffect(() => {
    const btn = navRef.current?.children[cur]
    btn?.scrollIntoView({ behavior:'smooth', block:'nearest', inline:'center' })
  }, [cur])

  const go = (idx) => setCur(Math.max(0, Math.min(total - 1, idx)))

  return (
    <section id="showcase">
      {/* 헤더 */}
      <div style={{ marginBottom:16 }}>
        <h2 style={{ fontSize:19, fontWeight:700, marginBottom:6 }}>Components Gallery</h2>
        <p style={{ fontSize:13.5, color:'#4B5563' }}>
          <code>@seed-design/css/recipes/*.css</code> 실제 클래스 구조 재현.
          현재 <strong>{total}</strong>개 검수 완료.
        </p>
      </div>

      {/* 상단 토글 네비 */}
      <div className="comp-nav" ref={navRef}>
        {COMPONENTS.map((c, i) => (
          <button key={c.name}
            className={`comp-nav-btn${i === cur ? ' active' : ''}`}
            onClick={() => go(i)}>
            {c.name}
          </button>
        ))}
      </div>

      {/* 캐러셀 — wrapper 너비를 JS로 측정해 슬라이드에 px 직접 지정 */}
      <div className="comp-carousel-wrap" ref={wrapRef}>
        <div className="comp-carousel-track"
          style={{ transform: `translateX(${-cur * slideW}px)` }}>
          {COMPONENTS.map((c) => (
            <div key={c.name} className="comp-carousel-slide"
              style={{ width: slideW || '100%' }}>
              {c.demo}
            </div>
          ))}
        </div>
      </div>

